WITH enriched AS (SELECT *, LEAD(sqft, 2, 0) OVER (PARTITION BY region, city ORDER BY opened_date, id) AS next_sqft, STDDEV_SAMP(sqft) OVER (PARTITION BY city) AS city_stddev_samp_sqft FROM stores) SELECT id, store_name, city, sqft, next_sqft, city_stddev_samp_sqft, CASE WHEN store_name RLIKE '^(Old Town|Siam Flagship)$' THEN 'EXTENDED' ELSE 'CORE' END AS store_name_zone FROM enriched
